	"document" text NOT NULL,
	"status" text NOT NULL,
	"reviewed_at" date,
	"note" text,
	"is_demo" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payment_documents_holder" CHECK ("payment_documents"."holder_kind" IN ('agente', 'vendedor', 'agencia')),
	CONSTRAINT "payment_documents_document" CHECK ("payment_documents"."document" IN ('w9', 'direct_deposit', 'voided_check')),
	CONSTRAINT "payment_documents_status" CHECK ("payment_documents"."status" IN ('pendiente', 'recibido', 'aprobado', 'rechazado'))
);
